#include <format>
#include <iostream>
#include <optional>
#include <span>
#include <string>
#include <vector>

[[nodiscard]] std::optional<int> single_reading(std::span<const int> v) {
  const std::ptrdiff_t n = std::ssize(v);
  if (n % 2 == 0) return std::nullopt;  // an even count pairs up completely
  std::ptrdiff_t lo = 0;
  std::ptrdiff_t hi = n - 1;
  while (lo < hi) {
    std::ptrdiff_t mid = lo + (hi - lo) / 2;
    if (mid % 2 == 1) --mid;  // keep mid even, so mid and mid + 1 are a candidate pair
    if (v[mid] == v[mid + 1]) {
      lo = mid + 2;  // the pair holds, the single value is further right
    } else {
      hi = mid;  // the pair is broken, the single value is at or before mid
    }
  }
  return v[lo];
}

[[nodiscard]] std::string show(const std::optional<int>& value) {
  return value ? std::format("{}", *value) : "no value";
}

int main() {
  const std::vector<int> a{1, 1, 2, 3, 3, 4, 4};
  const std::vector<int> b{1, 1, 2, 2, 3, 3};
  const std::vector<int> c{5};
  const std::vector<int> d{1, 1, 2, 2, 3, 4, 4, 5, 5};
  const std::vector<int> e{1, 1};
  const std::vector<int> f{1, 1, 2, 2, 3};
  std::cout << std::format("{} {} {} {}\n", show(single_reading(a)), show(single_reading(b)),
                           show(single_reading(c)), show(single_reading(d)));
  std::cout << std::format("{} {} empty: {}\n", show(single_reading(e)), show(single_reading(f)),
                           show(single_reading({})));
}

#include <cstddef>
#include <format>
#include <iostream>
#include <optional>
#include <span>
#include <string>
#include <unordered_set>
#include <vector>

struct Node {
  int value = 0;
  std::optional<std::ptrdiff_t> next;  // index of the next node in the same arena, or no value at the end
};

using Link = std::optional<std::ptrdiff_t>;

[[nodiscard]] Link first_shared_node(std::span<const Node> nodes, Link a, Link b) {
  std::unordered_set<std::ptrdiff_t> seen;
  for (Link at = a; at; at = nodes[*at].next) seen.insert(*at);
  for (Link at = b; at; at = nodes[*at].next) {
    if (seen.contains(*at)) return at;
  }
  return std::nullopt;
}

[[nodiscard]] std::string show(Link at) { return at ? std::format("index {}", *at) : "no value"; }

int main() {
  const std::vector<Node> nodes{
      {.value = 1, .next = 1},             // 0
      {.value = 2, .next = 5},             // 1
      {.value = 9, .next = 3},             // 2
      {.value = 8, .next = 4},             // 3
      {.value = 4, .next = 5},             // 4
      {.value = 7, .next = 6},             // 5, the first shared node
      {.value = 3, .next = std::nullopt},  // 6
      {.value = 42, .next = std::nullopt}, // 7, a separate list
      {.value = 43, .next = std::nullopt}, // 8, another separate list
  };
  std::cout << "shared:      " << show(first_shared_node(nodes, 0, 2)) << '\n';
  std::cout << "no overlap:  " << show(first_shared_node(nodes, 7, 8)) << '\n';
  std::cout << "one empty:   " << show(first_shared_node(nodes, 0, std::nullopt)) << '\n';
  std::cout << "both empty:  " << show(first_shared_node(nodes, std::nullopt, std::nullopt)) << '\n';
}
